1	//! Enforcement test for audit pattern B: outside `callisto-model` and
2	//! `callisto-manifests`, no crate should hand-parse `Cargo.toml`/
3	//! `package.json`/`pyproject.toml` (i.e. reference one of those file names
4	//! as a raw string literal *and* independently invoke a raw TOML/JSON
5	//! parse in the same file) instead of going through the shared readers in
6	//! `callisto_manifests` (`cargo_package_name`/`npm_package_name`/
7	//! `python_package_name`, `read_identity`, `read_napi_targets`).
8	//!
9	//! This is a coarse, file-level, production-code-only grep -- a regression
10	//! tripwire against *new* hand-parsing, not a precise static analyzer. Test
11	//! modules (`#[cfg(test)] mod ...`) are stripped before checking, since
12	//! test fixtures legitimately write out manifest files with these names.
13	//!
14	//! A handful of files are allowlisted below because they parse these
15	//! manifests for a genuinely different purpose than package-identity
16	//! (name/version) extraction -- see each entry's reason.
17	
18	use std::fs;
19	use std::path::{Path, PathBuf};
20	
21	/// Files allowed to contain a manifest-filename literal alongside a raw
22	/// parse call in production code, and why. Paths are relative to the
23	/// workspace root, forward-slash separated.
24	const ALLOWLIST: &[(&str, &str)] = &[
25	    (
26	        "crates/callisto-graph/src/locate/root.rs",
27	        "workspace-root marker detection (`[workspace]` / `workspaces` field presence), \
28	         not package identity extraction",
29	    ),
30	    (
31	        "crates/callisto-graph/src/locate/membership.rs",
32	        "workspace membership (members/exclude/workspaces glob) parsing, not package identity \
33	         extraction; already routes canonical manifest file names through \
34	         `ManifestFormat::*.file_name()` (audit pattern B, item 3)",
35	    ),
36	    (
37	        "crates/callisto-graph/src/napi.rs",
38	        "parses package.json into a serde_json::Value only to hand to the shared \
39	         callisto_manifests::read_napi_targets -- the field-extraction logic itself lives in \
40	         callisto-manifests, not here",
41	    ),
42	    (
43	        "crates/callisto-graph/src/matrix.rs",
44	        "parses package.json/pyproject.toml generically to extract non-identity fields \
45	         (engines.node, requires-python, [tool.maturin]); napi.targets extraction itself is \
46	         delegated to the shared callisto_manifests::read_napi_targets",
47	    ),
48	];
49	
50	const MANIFEST_LITERALS: [&str; 3] = ["\"Cargo.toml\"", "\"package.json\"", "\"pyproject.toml\""];
51	const PARSE_MARKERS: [&str; 3] = ["toml_edit::Document", "serde_json::from_str", ".parse::<toml_edit"];
52	
53	fn workspace_root() -> PathBuf {
54	    // CARGO_MANIFEST_DIR for this test binary is crates/callisto-graph;
55	    // the workspace root is two levels up.
56	    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
57	        .parent()
58	        .and_then(Path::parent)
59	        .expect("callisto-graph must be nested two levels under the workspace root")
60	        .to_path_buf()
61	}
62	
63	/// Strips every `#[cfg(test)] mod ... { ... }` block from `content` via
64	/// brace-depth tracking, rather than truncating at the first occurrence --
65	/// several files in this workspace interleave multiple `#[cfg(test)]`
66	/// modules with production code rather than appending one at the very end
67	/// (e.g. `locate/membership.rs`).
68	fn strip_test_modules(content: &str) -> String {
69	    let lines: Vec<&str> = content.lines().collect();
70	    let mut out = String::with_capacity(content.len());
71	    let mut i = 0;
72	    while i < lines.len() {
73	        if lines[i].trim() == "#[cfg(test)]" {
74	            i += 1;
75	            let mut depth: i32 = 0;
76	            let mut started = false;
77	            while i < lines.len() {
78	                for ch in lines[i].chars() {
79	                    match ch {
80	                        '{' => {
81	                            depth += 1;
82	                            started = true;
83	                        }
84	                        '}' => depth -= 1,
85	                        _ => {}
86	                    }
87	                }
88	                i += 1;
89	                if started && depth <= 0 {
90	                    break;
91	                }
92	            }
93	            continue;
94	        }
95	        out.push_str(lines[i]);
96	        out.push('\n');
97	        i += 1;
98	    }
99	    out
100	}
101	
102	fn collect_rust_src_files(dir: &Path, out: &mut Vec<PathBuf>) {
103	    let Ok(entries) = fs::read_dir(dir) else {
104	        return;
105	    };
106	    for entry in entries.flatten() {
107	        let path = entry.path();
108	        if path.is_dir() {
109	            collect_rust_src_files(&path, out);
110	        } else if path.extension().and_then(|e| e.to_str()) == Some("rs") {
111	            out.push(path);
112	        }
113	    }
114	}
115	
116	#[test]
117	fn no_hand_rolled_manifest_parsing_outside_model_and_manifests_crates() {
118	    let root = workspace_root();
119	    let crates_dir = root.join("crates");
120	
121	    let crate_dirs = fs::read_dir(&crates_dir)
122	        .unwrap_or_else(|e| panic!("could not read workspace crates dir at {crates_dir:?}: {e}"));
123	
124	    let mut violations = Vec::new();
125	
126	    for entry in crate_dirs.flatten() {
127	        let crate_path = entry.path();
128	        if !crate_path.is_dir() {
129	            continue;
130	        }
131	        let crate_name = crate_path.file_name().and_then(|n| n.to_str()).unwrap_or_default();
132	        if crate_name == "callisto-model" || crate_name == "callisto-manifests" {
133	            continue;
134	        }
135	
136	        let src_dir = crate_path.join("src");
137	        if !src_dir.is_dir() {
138	            continue;
139	        }
140	
141	        let mut files = Vec::new();
142	        collect_rust_src_files(&src_dir, &mut files);
143	
144	        for file in files {
145	            let Ok(content) = fs::read_to_string(&file) else {
146	                continue;
147	            };
148	            let production = strip_test_modules(&content);
149	
150	            let has_manifest_literal = MANIFEST_LITERALS.iter().any(|lit| production.contains(lit));
151	            let has_raw_parse = PARSE_MARKERS.iter().any(|marker| production.contains(marker));
152	
153	            if has_manifest_literal && has_raw_parse {
154	                let rel = file
155	                    .strip_prefix(&root)
156	                    .unwrap_or(&file)
157	                    .to_string_lossy()
158	                    .replace('\\', "/");
159	                if !ALLOWLIST.iter().any(|(path, _reason)| *path == rel) {
160	                    violations.push(rel);
161	                }
162	            }
163	        }
164	    }
165	
166	    assert!(
167	        violations.is_empty(),
168	        "found hand-rolled manifest parsing outside callisto-model/callisto-manifests (a \
169	         Cargo.toml/package.json/pyproject.toml literal alongside a raw toml_edit/serde_json \
170	         parse call) in production code -- route through callisto_manifests::{{cargo_package_name, \
171	         npm_package_name, python_package_name, read_identity, read_napi_targets}} instead, or add \
172	         a justified entry to this test's ALLOWLIST: {violations:#?}"
173	    );
174	}
175	
176	/// Keeps the allowlist honest: an entry naming a file that no longer exists
177	/// (renamed, deleted, or fully migrated) should be removed, not silently
178	/// carried forward.
179	#[test]
180	fn allowlist_entries_reference_files_that_still_exist() {
181	    let root = workspace_root();
182	    for (path, _reason) in ALLOWLIST {
183	        assert!(
184	            root.join(path).exists(),
185	            "allowlisted path no longer exists, remove this entry: {path}"
186	        );
187	    }
188	}
189	
190	// --- SPEC-ARCH-RELEASE-ERROR-TAXONOMY, PR1 -------------------------------
191	//
192	// Enforcement for the `GraphError::ReleaseIntentStale` (E124) struct-variant
193	// migration: staleness must carry a real `StaleReason`, real reasons are
194	// constructible only from `commands/release.rs`, and every other prior
195	// discard site is a tracked, shrinking migration ratchet rather than a
196	// silent, permanent hole.
197	
198	/// This crate's own `src/` directory, independent of `workspace_root()`
199	/// (which points at the whole-workspace root two levels up).
200	fn graph_crate_src_dir() -> PathBuf {
201	    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src")
202	}
203	
204	/// Reads `relative` (forward-slash separated, relative to this crate's
205	/// `src/`, e.g. `"commands/release.rs"`) with `#[cfg(test)] mod tests { ... }`
206	/// blocks stripped.
207	fn read_production_source(relative: &str) -> String {
208	    let path = graph_crate_src_dir().join(relative);
209	    let content = fs::read_to_string(&path).unwrap_or_else(|e| panic!("could not read {path:?}: {e}"));
210	    strip_test_modules(&content)
211	}
212	
213	/// `StaleReason`'s four real fresh-re-observation constructors (AC-001).
214	/// `legacy_unclassified` is deliberately excluded: it is the migration
215	/// ratchet, callable crate-wide by design during PR1-PR4.
216	const STALE_REASON_REAL_CONSTRUCTORS: [&str; 4] = [
217	    "trust_evidence_changed",
218	    "source_identity_changed",
219	    "git_remote_changed",
220	    "intent_differs_from_fresh_derivation",
221	];
222	
223	/// AC-002: the real fresh-re-observation privacy boundary is the four named
224	/// constructors, not the `ReleaseIntentStale` variant name -- that name
225	/// legitimately appears crate-wide via the `StaleReason::legacy_unclassified()`
226	/// ratchet while PR1-PR4 migrate every non-fresh-reobservation site.
227	#[test]
228	fn release_intent_stale_is_constructed_only_by_fresh_reobservation() {
229	    let release_rs = graph_crate_src_dir().join("commands/release.rs");
230	    let mut files = Vec::new();
231	    collect_rust_src_files(&graph_crate_src_dir(), &mut files);
232	
233	    let mut violations = Vec::new();
234	    for file in files {
235	        if file == release_rs {
236	            continue;
237	        }
238	        let Ok(content) = fs::read_to_string(&file) else {
239	            continue;
240	        };
241	        let production = strip_test_modules(&content);
242	        for name in STALE_REASON_REAL_CONSTRUCTORS {
243	            if production.contains(name) {
244	                violations.push(format!("{}: references `{name}`", file.display()));
245	            }
246	        }
247	    }
248	
249	    assert!(
250	        violations.is_empty(),
251	        "StaleReason's real fresh-re-observation constructors must be referenced only from \
252	         commands/release.rs; every other production site must use \
253	         StaleReason::legacy_unclassified() during the PR1-PR4 migration: {violations:#?}"
254	    );
255	}
256	
257	/// AC-001: the four real constructors carry no visibility modifier --
258	/// callable only from within `commands/release.rs` itself.
259	#[test]
260	fn stale_reason_constructors_are_module_private() {
261	    let production = read_production_source("commands/release.rs");
262	
263	    let mut violations = Vec::new();
264	    for name in STALE_REASON_REAL_CONSTRUCTORS {
265	        let needle = format!("fn {name}");
266	        for line in production.lines() {
267	            if line.contains(&needle) && line.contains("pub") {
268	                violations.push(format!("`{name}` has a visibility modifier: {}", line.trim()));
269	            }
270	        }
271	    }
272	
273	    assert!(
274	        violations.is_empty(),
275	        "StaleReason's real constructors must carry no pub/pub(crate)/pub(super) visibility: {violations:#?}"
276	    );
277	}
278	
279	/// Files still permitted to discard their `map_err` closure's bound error.
280	/// Two distinct categories, both pre-existing and verified by re-reading the
281	/// crate rather than assumed:
282	/// - The two remaining release-executor files are this spec's own
283	///   PR1-out-of-scope sites (`release_execution.rs` was migrated in PR2;
284	///   PR3 migrates `release_decision.rs`, PR4 `release.rs`) -- shrink these
285	///   two to nothing by PR4.
286	/// - The other five predate this spec entirely and belong to the companion
287	///   SPEC-ARCH-ERROR-SOURCE-PRESERVATION-GATE.json, which widens this same
288	///   check workspace-wide; not migrated here.
289	///
290	/// Either way, this test's job is to block a *sixth* (or new PR1-scope)
291	/// file from adopting the pattern, not to re-litigate already-tracked ones.
292	const MAP_ERR_IGNORE_ALLOWLIST: &[&str] = &[
293	    "commands/release.rs",
294	    "commands/release_decision.rs",
295	    "locate/ignore_walk.rs",
296	    "config/resolve.rs",
297	    "cascade.rs",
298	    "commands/publish.rs",
299	    "commands/snapshot.rs",
300	];
301	
302	/// True if `content` contains a `map_err(|_ident| ...)` closure -- one whose
303	/// bound error parameter is never used, evading `clippy::map_err_ignore`
304	/// (which only matches the bare `|_|` spelling).
305	fn contains_map_err_ignore(content: &str) -> bool {
306	    let marker = "map_err(|_";
307	    let mut search_from = 0;
308	    while let Some(relative_pos) = content[search_from..].find(marker) {
309	        // `marker` itself ends in the closure parameter's leading `_`.
310	        let ident_start = search_from + relative_pos + marker.len() - 1;
311	        let rest = &content[ident_start..];
312	        let ident_len = rest
313	            .char_indices()
314	            .take_while(|(_, c)| c.is_alphanumeric() || *c == '_')
315	            .count();
316	        if rest[ident_len..].starts_with('|') {
317	            return true;
318	        }
319	        search_from = ident_start + ident_len.max(1);
320	    }
321	    false
322	}
323	
324	/// AC-003 (PR1 scope): zero `map_err(|_ident| ...)` source-discarding
325	/// closures anywhere in this crate except the three allowlisted
326	/// release-executor files. The allowlist must shrink to empty by PR4
327	/// (SPEC-ARCH-RELEASE-ERROR-TAXONOMY.json's `suggested_pr_sequence`); this
328	/// test still fails on a fourth, non-allowlisted file adopting the pattern.
329	#[test]
330	fn release_modules_never_discard_error_sources() {
331	    let src_dir = graph_crate_src_dir();
332	    let mut files = Vec::new();
333	    collect_rust_src_files(&src_dir, &mut files);
334	
335	    let mut violations = Vec::new();
336	    for file in files {
337	        let Ok(content) = fs::read_to_string(&file) else {
338	            continue;
339	        };
340	        let production = strip_test_modules(&content);
341	        if !contains_map_err_ignore(&production) {
342	            continue;
343	        }
344	        let relative = file
345	            .strip_prefix(&src_dir)
346	            .unwrap_or(&file)
347	            .to_string_lossy()
348	            .replace('\\', "/");
349	        if !MAP_ERR_IGNORE_ALLOWLIST.contains(&relative.as_str()) {
350	            violations.push(relative);
351	        }
352	    }
353	
354	    assert!(
355	        violations.is_empty(),
356	        "found a new map_err(|_ident| ...) source-discarding closure outside the tracked PR1-PR4 \
357	         allowlist ({MAP_ERR_IGNORE_ALLOWLIST:?}); report the real error cause instead: {violations:#?}"
358	    );
359	}
360	
361	/// AC-015 migration ratchet: exact `StaleReason::legacy_unclassified()` call
362	/// counts pinned per file. PR1 pinned release.rs=44, release_decision.rs=42,
363	/// release_execution.rs=2; PR2 lowered `release_execution.rs` to 0 (this
364	/// file's two sites now carry a real `GraphError::ArtifactManifest` /
365	/// `ReleasePreconditionUnmet` cause instead). PR3 lowers
366	/// `release_decision.rs` to 0, PR4 lowers `release.rs` to 0 and deletes the
367	/// constructor (and this test) entirely. Update a count here only when the
368	/// corresponding PR intentionally lowers it -- never to silence a failure.
369	#[test]
370	fn legacy_unclassified_ratchet() {
371	    let cases: &[(&str, usize)] = &[
372	        ("commands/release.rs", 44),
373	        ("commands/release_decision.rs", 42),
374	        ("commands/release_execution.rs", 0),
375	    ];
376	    for (relative, expected) in cases {
377	        let production = read_production_source(relative);
378	        let actual = production.matches("StaleReason::legacy_unclassified()").count();
379	        assert_eq!(
380	            actual, *expected,
381	            "{relative}: StaleReason::legacy_unclassified() count drifted from the pinned PR1 ratchet"
382	        );
383	    }
384	}
385	
386	/// AC-014: E124 is the sole owner of "reapprove" guidance -- every other
387	/// release-error variant's help text must describe its own real recovery
388	/// action instead of copying E124's.
389	#[test]
390	fn reapprove_guidance_belongs_to_e124_only() {
391	    let production = read_production_source("error.rs");
392	    let count = production.matches("reapprove").count();
393	    assert_eq!(
394	        count, 1,
395	        "'reapprove' must occur exactly once in error.rs (E124's help text only); found {count}"
396	    );
397	}
