34	/// Derives the durable roster from a freshly computed version plan.
35	///
36	/// The caller supplies the plan from the same workspace observation; this
37	/// function never inspects `PublishPlan` or a caller-provided release roster.
38	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
39	    workspace: &Workspace<'_, R, D>,
40	    plan: &VersionPlan,
41	) -> Result<ReleaseDecisionV1, GraphError> {
42	    let mut package_ids = std::collections::BTreeMap::new();
43	    for package in workspace.graph.packages() {
44	        let ids = release_package_ids(package)?;
45	        package_ids.insert(package.id.clone(), ids);
46	    }
47	
48	    let mut entries = Vec::new();
49	    for bump in &plan.bumps {
50	        let ids = package_ids.get(&bump.package).ok_or(GraphError::ReleaseIntentStale {
51	            reason: StaleReason::legacy_unclassified(),
52	        })?;
53	        for id in ids {
54	            entries.push(ReleaseDecisionEntry {
55	                package: id.clone(),
56	                target_version: bump.to.clone(),
57	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
58	            });
59	        }
60	    }
61	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale {
62	        reason: StaleReason::legacy_unclassified(),
63	    })
64	}
