66	/// Derives a durable decision for explicit, exact release identities.
67	///
68	/// A linked group is one release unit: selecting any member includes every
69	/// member of that linked group which the version plan selected. All other
70	/// packages remain outside the authority boundary. The caller must pass
71	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
72	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
73	/// for release authority.
74	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
75	    workspace: &Workspace<'_, R, D>,
76	    plan: &VersionPlan,
77	    selections: &[ReleasePackageId],
78	) -> Result<ReleaseDecisionV1, GraphError> {
79	    let complete = derive_release_decision(workspace, plan)?;
80	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
81	    if selected.len() != selections.len() {
82	        return Err(GraphError::ReleaseIntentStale {
83	            reason: StaleReason::legacy_unclassified(),
84	        });
85	    }
86	    if selected
87	        .iter()
88	        .any(|selection| !complete.entries.iter().any(|entry| &entry.package == *selection))
89	    {
90	        return Err(GraphError::ReleaseIntentStale {
91	            reason: StaleReason::legacy_unclassified(),
92	        });
93	    }
94	
95	    let linked_groups = complete
96	        .entries
97	        .iter()
98	        .filter(|entry| selected.contains(&entry.package))
99	        .flat_map(|entry| entry.reasons.iter())
100	        .filter_map(|reason| match reason {
101	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
102	            _ => None,
103	        })
104	        .collect::<std::collections::BTreeSet<_>>();
105	
106	    let entries = complete
107	        .entries
108	        .into_iter()
109	        .filter(|entry| {
110	            selected.contains(&entry.package)
111	                || entry.reasons.iter().any(|reason| {
112	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if linked_groups.contains(group_id))
113	                })
114	        })
115	        .collect();
116	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale {
117	        reason: StaleReason::legacy_unclassified(),
118	    })
119	}
