121	/// Verifies the release roster a merged release commit claims, against a
122	/// release-decision file committed alongside it at `decision_path`.
123	///
124	/// This is intentionally *not* a second computation of changeset, fixed-group,
125	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
126	/// (via [`derive_release_decision`]) already computed that once, correctly,
127	/// when the release PR was generated -- and `callisto version --emit-decision`
128	/// commits its exact output alongside the manifest and changelog edits.
129	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
130	/// the kind of duplicated logic that drifts: an earlier version of this
131	/// function did just that, understood only a direct changeset match, and
132	/// rejected every real release in this repository once a fixed-group cascade
133	/// (a case its reimplementation never learned) touched an unnamed sibling.
134	///
135	/// Instead, this function reads the committed decision back and confirms the
136	/// commit's actual diff matches it exactly -- no more, no less.
137	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
138	/// entries don't match its content digest, so a hand-edited or corrupted
139	/// decision file fails before this function's own diff cross-check runs.
140	///
141	/// The caller must check out the exact merge commit in detached HEAD state
142	/// before creating an intent. GitHub-specific PR/approval provenance belongs
143	/// in the workflow boundary; this graph function verifies the local,
144	/// provider-neutral commit delta only.
145	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
146	    workspace: &Workspace<'_, R, D>,
147	    release_commit: &CommitSha,
148	    decision_path: &std::path::Path,
149	) -> Result<ReleaseDecisionV1, GraphError> {
150	    let head = git_stdout(workspace.runner, &workspace.root, &["rev-parse", "HEAD"])?;
151	    let head = CommitSha::parse(&head).map_err(|_error| GraphError::ReleaseIntentStale {
152	        reason: StaleReason::legacy_unclassified(),
153	    })?;
154	    if &head != release_commit {
155	        return Err(GraphError::ReleaseIntentStale {
156	            reason: StaleReason::legacy_unclassified(),
157	        });
158	    }
159	
160	    let parent_ref = format!("{}^", release_commit.as_str());
161	    let parent = git_stdout(workspace.runner, &workspace.root, &["rev-parse", &parent_ref])?;
162	    CommitSha::parse(&parent).map_err(|_error| GraphError::ReleaseIntentStale {
163	        reason: StaleReason::legacy_unclassified(),
164	    })?;
165	
166	    let changed = git_stdout(
167	        workspace.runner,
168	        &workspace.root,
169	        &[
170	            "diff-tree",
171	            "--no-commit-id",
172	            "--name-status",
173	            "-r",
174	            "--no-renames",
175	            &parent,
176	            release_commit.as_str(),
177	        ],
178	    )?;
179	    let changed = parse_name_status(&changed)?;
180	
181	    // The decision must be freshly authored as part of *this* commit, not a
182	    // stale leftover an earlier release already committed and this one never
183	    // touched -- otherwise a commit that changes nothing real could still
184	    // carry forward a prior, unrelated decision's authority.
185	    let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
186	    let decision_freshly_written = changed
187	        .iter()
188	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
189	    if !decision_freshly_written {
190	        return Err(GraphError::ReleaseIntentStale {
191	            reason: StaleReason::legacy_unclassified(),
192	        });
193	    }
194	
195	    // A cheap, independent sanity check that this commit is a real version
196	    // application and not just a hand-crafted decision file: some real
197	    // changeset was actually consumed. The decision's own entries, not this
198	    // changeset's content, remain the sole authority verified below.
199	    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
200	    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
201	    let consumed_a_changeset = changed
202	        .iter()
203	        .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
204	    if !consumed_a_changeset {
205	        return Err(GraphError::ReleaseIntentStale {
206	            reason: StaleReason::legacy_unclassified(),
207	        });
208	    }
209	
210	    let decision_source = git_file(
211	        workspace.runner,
212	        &workspace.root,
213	        release_commit.as_str(),
214	        &decision_path_str,
215	    )?;
216	    let decision: ReleaseDecisionV1 =
217	        serde_json::from_str(&decision_source).map_err(|_error| GraphError::ReleaseIntentStale {
218	            reason: StaleReason::legacy_unclassified(),
219	        })?;
220	    let claimed = decision
221	        .entries
222	        .iter()
223	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
224	        .collect::<std::collections::BTreeMap<_, _>>();
225	
226	    let changed_paths = changed
227	        .iter()
228	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
229	        .collect::<std::collections::BTreeSet<_>>();
230	
231	    // Every canonical manifest path this workspace currently declares, in
232	    // the exact order `workspace.graph.packages()` and
233	    // `Package::canonical_manifests()` yield -- both are backed by ordered
234	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
235	    // the second traversal below visits the same (package, manifest) pairs
236	    // in the same order. That lets it zip the batched `before`/`after`
237	    // results back on by position instead of re-keying by path, which would
238	    // misbehave if two packages ever declared an identical manifest path.
239	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
240	        .graph
241	        .packages()
242	        .flat_map(Package::canonical_manifests)
243	        .map(|manifest| (manifest.path.to_string_lossy().into_owned(), manifest.ecosystem()))
244	        .collect();
245	    let query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();
246	
247	    // Exactly two `git cat-file --batch` subprocess invocations total (one
248	    // per commit), regardless of how many canonical manifests the
249	    // workspace has -- replaces what was previously 2*N separate `git
250	    // show` spawns (one `manifest_version_at` call per manifest per
251	    // commit).
252	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
253	    let after_blobs =
254	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
255	    let before_versions = resolve_batch_versions(before_blobs, &manifest_queries)?;
256	    let after_versions = resolve_batch_versions(after_blobs, &manifest_queries)?;
257	
258	    let mut observed = std::collections::BTreeSet::new();
259	    let mut manifest_index = 0usize;
260	    for package in workspace.graph.packages() {
261	        let package_ids = release_package_ids(package)?;
262	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
263	        if package_is_claimed {
264	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleaseIntentStale {
265	                reason: StaleReason::legacy_unclassified(),
266	            })?;
267	            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
268	                return Err(GraphError::ReleaseIntentStale {
269	                    reason: StaleReason::legacy_unclassified(),
270	                });
271	            }
272	        }
273	        for (manifest, id) in package.canonical_manifests().zip(package_ids) {
274	            let path = manifest.path.to_string_lossy();
275	            let before = &before_versions[manifest_index];
276	            let after = &after_versions[manifest_index];
277	            manifest_index += 1;
278	            let changed_version = before != after;
279	            match claimed.get(&id) {
280	                Some(target_version) => {
281	                    if !changed_version || after != target_version || !changed_paths.contains(path.as_ref()) {
282	                        return Err(GraphError::ReleaseIntentStale {
283	                            reason: StaleReason::legacy_unclassified(),
284	                        });
285	                    }
286	                    observed.insert(id);
287	                }
288	                None => {
289	                    if changed_version {
290	                        // A changed version the committed decision never
291	                        // claimed is not this commit's authority -- fail
292	                        // closed rather than trust a partial match.
293	                        return Err(GraphError::ReleaseIntentStale {
294	                            reason: StaleReason::legacy_unclassified(),
295	                        });
296	                    }
297	                }
298	            }
299	        }
300	    }
301	    if observed.len() != claimed.len() {
302	        return Err(GraphError::ReleaseIntentStale {
303	            reason: StaleReason::legacy_unclassified(),
304	        });
305	    }
306	
307	    Ok(decision)
308	}
