310	fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
311	    let output = runner.run("git", args, root)?;
312	    if !output.success() {
313	        return Err(GraphError::ReleaseIntentStale {
314	            reason: StaleReason::legacy_unclassified(),
315	        });
316	    }
317	    Ok(output.stdout_trimmed().to_string())
318	}
