320	fn parse_name_status(output: &str) -> Result<Vec<(String, String)>, GraphError> {
321	    output
322	        .lines()
323	        .map(|line| {
324	            let (status, path) = line.split_once('\t').ok_or(GraphError::ReleaseIntentStale {
325	                reason: StaleReason::legacy_unclassified(),
326	            })?;
327	            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
328	                return Err(GraphError::ReleaseIntentStale {
329	                    reason: StaleReason::legacy_unclassified(),
330	                });
331	            }
332	            Ok((status.to_string(), path.to_string()))
333	        })
334	        .collect()
335	}
