337	fn git_file<R: CommandRunner>(
338	    runner: &R,
339	    root: &std::path::Path,
340	    commit: &str,
341	    path: &str,
342	) -> Result<String, GraphError> {
343	    let object = format!("{commit}:{path}");
344	    git_stdout(runner, root, &["show", &object])
345	}
346	
347	/// Extracts a manifest's declared version from its already-fetched raw
348	/// source text. Shared by the batched `git cat-file --batch` path in
349	/// [`derive_release_commit_decision`] (via [`resolve_batch_versions`]) and
350	/// this module's own tests (via the single-object `manifest_version_at`
351	/// helper they define), so both use identical parsing rules.
352	fn parse_manifest_version(source: &str, path: &str, ecosystem: Ecosystem) -> Result<Version, GraphError> {
353	    let format = ecosystem
354	        .canonical_manifest_format()
355	        .ok_or(GraphError::ReleaseIntentStale {
356	            reason: StaleReason::legacy_unclassified(),
357	        })?;
358	    // A malformed blob, a version-less manifest (e.g. a Cargo workspace
359	    // root with no [package] table, or a `dynamic = ["version"]` PEP 621
360	    // package), or a Cargo `version.workspace = true` inheritance (which
361	    // `read_identity` deliberately never resolves, having no workspace
362	    // context for a historical git blob) all fail closed here rather than
363	    // panicking or fabricating a version.
364	    let version = callisto_manifests::read_identity(format, source, std::path::Path::new(path))
365	        .ok()
366	        .and_then(|identity| match identity.version {
367	            Some(callisto_manifests::VersionSource::Literal(v)) => Some(v),
368	            _ => None,
369	        })
370	        .ok_or(GraphError::ReleaseIntentStale {
371	            reason: StaleReason::legacy_unclassified(),
372	        })?;
373	    Version::parse(&version, ecosystem.version_grammar()).map_err(|_error| GraphError::ReleaseIntentStale {
374	        reason: StaleReason::legacy_unclassified(),
375	    })
376	}
