378	/// One object's content as reported by `git cat-file --batch`, for a single
379	/// requested `<commit>:<path>`.
380	enum BatchBlob {
381	    /// The path resolved to a blob at the queried commit; this is its raw
382	    /// content.
383	    Blob(String),
384	    /// The path did not exist at the queried commit -- e.g. a package's
385	    /// manifest that was only added later, so it has no blob yet at an
386	    /// earlier `parent` commit.
387	    Missing,
388	}
389	
390	/// Issues exactly one `git cat-file --batch` invocation requesting every
391	/// path in `paths` as `<commit>:<path>`, and returns each result in the
392	/// same order as `paths`.
393	///
394	/// `git cat-file --batch` reads one object identifier per line from stdin
395	/// and, for each, writes to stdout either:
396	///
397	/// ```text
398	/// <sha> SP <type> SP <size> LF
399	/// <content: exactly `size` bytes> LF
400	/// ```
401	///
402	/// or, if the object doesn't exist:
403	///
404	/// ```text
405	/// <object> SP missing LF
406	/// ```
407	///
408	/// (git also reports `<object> SP ambiguous LF` for a ref that resolves to
409	/// more than one object; `<commit>:<path>` syntax should never be
410	/// ambiguous, but it's checked for explicitly below rather than silently
411	/// falling through to the blob-header parse.)
412	///
413	/// This lets every canonical manifest's content at one commit be fetched in
414	/// a single subprocess round trip instead of one `git show` per manifest.
415	///
416	/// Parsing here is deliberately defensive rather than permissive: this
417	/// feeds [`derive_release_commit_decision`]'s trust-boundary comparison, so
418	/// any framing ambiguity -- an unrecognized header shape, a declared `size`
419	/// that doesn't fit the remaining output, a missing separator byte right
420	/// after the declared content length, a non-`blob` object type, or a
421	/// leftover/truncated tail once every requested path has been accounted
422	/// for -- fails the whole batch closed rather than guessing. Each expected
423	/// response is also matched against its exact requested object string
424	/// (rather than a generic "ends with ` missing`" pattern), so a manifest
425	/// path that happened to contain a space or colon can't be misread as a
426	/// different response shape. Silently misattributing one manifest's
427	/// content to a different path because an undetected desync shifted every
428	/// later offset would be a far worse failure mode than an outright
429	/// rejection.
430	fn batch_manifest_blobs_at<R: CommandRunner>(
431	    runner: &R,
432	    root: &std::path::Path,
433	    commit: &str,
434	    paths: &[&str],
435	) -> Result<Vec<BatchBlob>, GraphError> {
436	    if paths.is_empty() {
437	        return Ok(Vec::new());
438	    }
439	
440	    let mut stdin = String::new();
441	    let objects: Vec<String> = paths
442	        .iter()
443	        .map(|path| {
444	            let object = format!("{commit}:{path}");
445	            stdin.push_str(&object);
446	            stdin.push('\n');
447	            object
448	        })
449	        .collect();
450	
451	    let output = runner
452	        .run_with_stdin("git", &["cat-file", "--batch"], root, stdin.as_bytes())
453	        .map_err(|_error| GraphError::ReleaseIntentStale {
454	            reason: StaleReason::legacy_unclassified(),
455	        })?;
456	    if !output.success() {
457	        return Err(GraphError::ReleaseIntentStale {
458	            reason: StaleReason::legacy_unclassified(),
459	        });
460	    }
461	
462	    let mut rest = output.stdout.as_str();
463	    let mut results = Vec::with_capacity(objects.len());
464	    for object in &objects {
465	        let (header, after_header) = rest.split_once('\n').ok_or(GraphError::ReleaseIntentStale {
466	            reason: StaleReason::legacy_unclassified(),
467	        })?;
468	
469	        if header == format!("{object} missing") {
470	            results.push(BatchBlob::Missing);
471	            rest = after_header;
472	            continue;
473	        }
474	        if header == format!("{object} ambiguous") {
475	            return Err(GraphError::ReleaseIntentStale {
476	                reason: StaleReason::legacy_unclassified(),
477	            });
478	        }
479	
480	        let mut fields = header.split(' ');
481	        let sha = fields.next().ok_or(GraphError::ReleaseIntentStale {
482	            reason: StaleReason::legacy_unclassified(),
483	        })?;
484	        let object_type = fields.next().ok_or(GraphError::ReleaseIntentStale {
485	            reason: StaleReason::legacy_unclassified(),
486	        })?;
487	        let size_field = fields.next().ok_or(GraphError::ReleaseIntentStale {
488	            reason: StaleReason::legacy_unclassified(),
489	        })?;
490	        if fields.next().is_some() {
491	            // A well-formed header has exactly three space-separated
492	            // fields; anything else is not a shape this parser understands.
493	            return Err(GraphError::ReleaseIntentStale {
494	                reason: StaleReason::legacy_unclassified(),
495	            });
496	        }
497	        if sha.is_empty() || !sha.chars().all(|c| c.is_ascii_hexdigit()) {
498	            return Err(GraphError::ReleaseIntentStale {
499	                reason: StaleReason::legacy_unclassified(),
500	            });
501	        }
502	        if object_type != "blob" {
503	            // Every path requested here is a canonical manifest file, so a
504	            // resolved object must be a blob; a tree/commit/tag response
505	            // means the path resolved to something else entirely.
506	            return Err(GraphError::ReleaseIntentStale {
507	                reason: StaleReason::legacy_unclassified(),
508	            });
509	        }
510	        let size: usize = size_field.parse().map_err(|_error| GraphError::ReleaseIntentStale {
511	            reason: StaleReason::legacy_unclassified(),
512	        })?;
513	
514	        if size > after_header.len() {
515	            return Err(GraphError::ReleaseIntentStale {
516	                reason: StaleReason::legacy_unclassified(),
517	            });
518	        }
519	        // `.get(..size)` (byte-indexed) rather than raw slicing: if `size`
520	        // doesn't land on a UTF-8 char boundary this fails closed instead
521	        // of panicking.
522	        let content = after_header.get(..size).ok_or(GraphError::ReleaseIntentStale {
523	            reason: StaleReason::legacy_unclassified(),
524	        })?;
525	        let remainder = &after_header[size..];
526	        // The protocol always emits exactly one LF right after the
527	        // content, separate from the content itself. Requiring it here
528	        // catches a desynced `size` (from an earlier, unexpectedly
529	        // reencoded entry) as an explicit error instead of silently
530	        // parsing the wrong bytes as this entry's content.
531	        if remainder.as_bytes().first() != Some(&b'\n') {
532	            return Err(GraphError::ReleaseIntentStale {
533	                reason: StaleReason::legacy_unclassified(),
534	            });
535	        }
536	        results.push(BatchBlob::Blob(content.to_string()));
537	        rest = &remainder[1..];
538	    }
539	
540	    if !rest.is_empty() {
541	        // More output than the requested objects account for -- either an
542	        // extra unexpected reply or a framing desync earlier in the
543	        // stream. Either way, fail closed rather than ignore it.
544	        return Err(GraphError::ReleaseIntentStale {
545	            reason: StaleReason::legacy_unclassified(),
546	        });
547	    }
548	
549	    Ok(results)
550	}
