552	/// Converts each batched blob-fetch result into the [`Version`] the
553	/// equivalent single-object `git show` fetch would have produced, using
554	/// [`parse_manifest_version`]'s parsing rules. A path missing from the
555	/// queried commit fails closed exactly as a `git show` that couldn't
556	/// resolve the path would have.
557	fn resolve_batch_versions(blobs: Vec<BatchBlob>, queries: &[(String, Ecosystem)]) -> Result<Vec<Version>, GraphError> {
558	    blobs
559	        .into_iter()
560	        .zip(queries.iter())
561	        .map(|(blob, (path, ecosystem))| match blob {
562	            BatchBlob::Blob(source) => parse_manifest_version(&source, path, *ecosystem),
563	            BatchBlob::Missing => Err(GraphError::ReleaseIntentStale {
564	                reason: StaleReason::legacy_unclassified(),
565	            }),
566	        })
567	        .collect()
568	}
