570	fn reason_from_bump(
571	    reason: Option<&BumpReason>,
572	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
573	) -> Result<ReleaseInclusionReason, GraphError> {
574	    match reason {
575	        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
576	        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
577	        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
578	            group_id: group.to_string(),
579	        }),
580	        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
581	            Ok(ReleaseInclusionReason::FixedGroup {
582	                group_id: group.to_string(),
583	            })
584	        }
585	        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
586	        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
587	            let source = package_ids
588	                .get(via)
589	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
590	                .ok_or(GraphError::ReleaseIntentStale {
591	                    reason: StaleReason::legacy_unclassified(),
592	                })?;
593	            Ok(ReleaseInclusionReason::Cascade {
594	                from: source,
595	                edge_kind: format!("{dep_kind:?}"),
596	            })
597	        }
598	        Some(BumpReason::PeerEscalation { via, .. }) => {
599	            let source = package_ids
600	                .get(via)
601	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
602	                .ok_or(GraphError::ReleaseIntentStale {
603	                    reason: StaleReason::legacy_unclassified(),
604	                })?;
605	            Ok(ReleaseInclusionReason::Cascade {
606	                from: source,
607	                edge_kind: "peer".to_string(),
608	            })
609	        }
610	        Some(_) => Err(GraphError::ReleaseIntentStale {
611	            reason: StaleReason::legacy_unclassified(),
612	        }),
613	    }
614	}
