782	    /// Records every `run`/`run_with_stdin` invocation and answers each the
783	    /// way a real `git` would for this test's fixed fixture, so
784	    /// `derive_release_commit_decision` can be driven entirely in-memory.
785	    /// `batch_calls` is the assertion this test cares about: it must land
786	    /// on exactly 2 (one `cat-file --batch` per commit) no matter how many
787	    /// canonical manifests `FixedManifestGraph` declares, proving the fix
788	    /// replaced 2*N `git show` spawns with 2 total, not N-scaled batches.
789	    struct CountingBatchRunner {
790	        release_commit: String,
791	        parent: String,
792	        decision_json: String,
793	        name_status: String,
794	        /// (commit, path) -> blob content; a path/commit pair with no entry
795	        /// here is answered as `missing`, matching real `git cat-file
796	        /// --batch` behavior for a path that doesn't exist at that commit.
797	        blobs: std::collections::BTreeMap<(String, String), String>,
798	        run_calls: std::sync::Mutex<Vec<(String, Vec<String>)>>,
799	        batch_calls: std::sync::Mutex<u32>,
800	    }
801	
802	    impl CommandRunner for CountingBatchRunner {
803	        fn run(
804	            &self,
805	            program: &str,
806	            args: &[&str],
807	            _cwd: &std::path::Path,
808	        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
809	            self.run_calls
810	                .lock()
811	                .unwrap()
812	                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));
813	
814	            let ok = |stdout: String| {
815	                Ok(callisto_model::CommandOutput {
816	                    exit_code: Some(0),
817	                    stdout,
818	                    stderr: String::new(),
819	                })
820	            };
821	            let rev_parse_parent = format!("{}^", self.release_commit);
822	            let decision_object = format!("{}:.callisto/release-decision.json", self.release_commit);
823	            if args.first().copied() == Some("rev-parse") && args.get(1).copied() == Some("HEAD") {
824	                return ok(self.release_commit.clone());
825	            }
826	            if args.first().copied() == Some("rev-parse") && args.get(1).copied() == Some(rev_parse_parent.as_str()) {
827	                return ok(self.parent.clone());
828	            }
829	            if args.first().copied() == Some("diff-tree") {
830	                return ok(self.name_status.clone());
831	            }
832	            if args.first().copied() == Some("show") && args.get(1).copied() == Some(decision_object.as_str()) {
833	                return ok(self.decision_json.clone());
834	            }
835	            panic!("unexpected `{program} {args:?}` in CountingBatchRunner::run");
836	        }
837	
838	        fn run_with_stdin(
839	            &self,
840	            program: &str,
841	            args: &[&str],
842	            _cwd: &std::path::Path,
843	            stdin: &[u8],
844	        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
845	            self.run_calls
846	                .lock()
847	                .unwrap()
848	                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));
849	            assert_eq!(program, "git");
850	            assert_eq!(args, ["cat-file", "--batch"]);
851	            *self.batch_calls.lock().unwrap() += 1;
852	
853	            let requested = std::str::from_utf8(stdin).expect("test stdin is always valid UTF-8");
854	            let mut stdout = String::new();
855	            for object in requested.lines() {
856	                let (commit, path) = object.split_once(':').expect("object identifier must be commit:path");
857	                match self.blobs.get(&(commit.to_string(), path.to_string())) {
858	                    Some(content) => {
859	                        stdout.push_str(&format!("{} blob {}\n{}\n", "0".repeat(40), content.len(), content));
860	                    }
861	                    None => {
862	                        stdout.push_str(&format!("{object} missing\n"));
863	                    }
864	                }
865	            }
866	            Ok(callisto_model::CommandOutput {
867	                exit_code: Some(0),
868	                stdout,
869	                stderr: String::new(),
870	            })
871	        }
872	    }
