use std::collections::HashSet;
use std::path::{Path, PathBuf};

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::{
    workspace_relative, Ecosystem, ModelError, PackageId, PublishTarget, ReleaseTrigger, TagTemplate, VersionGrammar,
};

/// A package in the workspace graph.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Package {
    pub id: PackageId,
    pub manifests: Vec<ManifestDecl>,
    pub changelog: Option<PathBuf>,
    pub release_trigger: ReleaseTrigger,
    pub publish_to: Vec<PublishTarget>,
    pub tag_template: Option<TagTemplate>,
}

impl Package {
    pub fn canonical_manifests(&self) -> impl Iterator<Item = &ManifestDecl> {
        self.manifests.iter().filter(|m| m.role == ManifestRole::Canonical)
    }

    pub fn platform_manifests(&self) -> impl Iterator<Item = &ManifestDecl> {
        self.manifests
            .iter()
            .filter(|m| matches!(m.role, ManifestRole::Platform { .. }))
    }

    pub fn lockfiles(&self) -> impl Iterator<Item = &ManifestDecl> {
        self.manifests.iter().filter(|m| m.role == ManifestRole::Lockfile)
    }

    pub fn version_grammar(&self) -> Result<VersionGrammar, ModelError> {
        let grammars: Vec<_> = self
            .canonical_manifests()
            .map(|m| m.format.ecosystem().version_grammar())

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::{ManifestFormat, NpmAccess, RegistryKey, VersionGrammar};

/// Ecosystem supported by callisto.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
#[non_exhaustive]
pub enum Ecosystem {
    Cargo,
    Npm,
    // Demand-gated ecosystems:
    Pypi,
    Go,
    Maven,
    NuGet,
    Deno,
    Jsr,
}

impl Ecosystem {
    /// The three ecosystems package *identity discovery* treats as
    /// canonical -- each has exactly one manifest format
    /// ([`Ecosystem::canonical_manifest_format`]) that carries a package's
    /// name and (usually) version. Deliberately excludes the other,
    /// demand-gated ecosystems in this enum (Go, Maven, NuGet, ...), which
    /// either have no canonical-identity manifest wired up yet or aren't
    /// part of this duplication (see audit pattern B).
    pub const CANONICAL: [Ecosystem; 3] = [Ecosystem::Cargo, Ecosystem::Npm, Ecosystem::Pypi];

    /// The manifest format that carries this ecosystem's package identity
    /// (name and version), for the [`Self::CANONICAL`] ecosystems only.
    /// `None` for every other ecosystem in this enum.
    pub fn canonical_manifest_format(&self) -> Option<ManifestFormat> {
        match self {
            Ecosystem::Cargo => Some(ManifestFormat::CargoToml),
            Ecosystem::Npm => Some(ManifestFormat::PackageJson),
            Ecosystem::Pypi => Some(ManifestFormat::PyprojectToml),
            _ => None,
        }
    }

    pub fn prefix(&self) -> &'static str {
        match self {
            Ecosystem::Cargo => "cargo",
